 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    boxes = []
    for color in range(1, 10):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not pts:
            continue
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        # Objects here are rectangular frames, possibly with same-color marks inside.
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        if not (all(grid[r0][c] == color for c in range(c0,c1+1)) and
                all(grid[r1][c] == color for c in range(c0,c1+1)) and
                all(grid[r][c0] == color for r in range(r0,r1+1)) and
                all(grid[r][c1] == color for r in range(r0,r1+1))):
            continue
        pattern = [[grid[r][c] == color for c in range(c0+1,c1)] for r in range(r0+1,r1)]
        boxes.append((color,r0,r1,c0,c1,pattern))
    # The frame containing interior marks provides the pattern; repeat it in
    # every frame with the same interior dimensions and discard other frames.
    src = next((b for b in boxes if any(any(row) for row in b[5])), None)
    if src is None:
        return out
    sh, sw = len(src[5]), len(src[5][0])
    for color,r0,r1,c0,c1,pattern in boxes:
        if (r1-r0-1, c1-c0-1) != (sh,sw):
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    out[r][c] = 0
            continue
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                out[r][c] = color if src[5][r-(r0+1)][c-(c0+1)] else 0
    return out
